const variant = new URLSearchParams(location.search).get('variant') === 'b' ? 'b' : 'a'; document.body.classList.toggle('b',variant==='b'); const sections=[['Чат','◉'],['Команды','⌘'],['Подключения','◇'],['Журнал','☷']]; const tabs=document.querySelector('.tabs'),rail=document.querySelector('.rail'); function select(name){document.querySelectorAll('.navbtn').forEach(b=>{const on=b.dataset.name===name;b.classList.toggle('active',on);b.setAttribute('aria-current',on?'page':'false')});document.querySelector('.content').hidden=name!=='Чат';document.querySelector('.page').hidden=name==='Чат';document.querySelector('.chat-head').hidden=name!=='Чат';document.querySelector('.page-title').textContent=name;document.body.classList.remove('drawer-open')};for(const target of [tabs,rail])for(const [name,icon] of sections){const b=document.createElement('button');b.className='navbtn';b.dataset.name=name;b.title=name;b.setAttribute('aria-label',name);b.innerHTML=`<span class="icon">${icon}</span><span class="label">${name}</span>`;b.onclick=()=>select(name);target.append(b)}select('Чат');document.querySelector('#settings').onclick=()=>select('Настройки');document.querySelector('#profile').onclick=()=>select('Профиль');document.querySelector('#back').onclick=()=>select('Чат');document.querySelector('#collapse').onclick=()=>{if(innerWidth<=900)document.body.classList.remove('drawer-open');else document.body.classList.add('collapsed')};document.querySelector('#expand').onclick=()=>{if(innerWidth<=900)document.body.classList.toggle('drawer-open');else document.body.classList.remove('collapsed')};document.querySelector('#search').oninput=e=>{let n=0;document.querySelectorAll('.conversation').forEach(b=>{b.hidden=!b.textContent.toLowerCase().includes(e.target.value.toLowerCase());if(!b.hidden)n++});document.querySelector('.empty').hidden=!!n};document.querySelectorAll('.conversation').forEach(b=>b.onclick=()=>{document.querySelectorAll('.conversation').forEach(x=>x.classList.remove('active'));b.classList.add('active');document.querySelector('#title').textContent=b.textContent;select('Чат')});document.querySelector('#new').onclick=()=>{document.querySelector('#title').textContent='Новый разговор';document.querySelector('#messages').innerHTML='<div class="greeting"><div class="eyebrow">NOX ASSISTANT</div><h1>Привет, Абу.</h1><p>Чем займёмся сегодня?</p></div>';select('Чат')};document.querySelector('#mode').onclick=e=>e.currentTarget.textContent=e.currentTarget.textContent.includes('Быстрая')?'Умная ﹀':'Быстрая ﹀';document.querySelector('#form').onsubmit=e=>{e.preventDefault();const t=e.currentTarget.querySelector('textarea');if(!t.value.trim())return;const m=document.createElement('div');m.className='message';m.textContent=t.value;const box=document.querySelector('#messages');box.replaceChildren(m);t.value=''};document.querySelectorAll('.win').forEach(b=>b.onclick=()=>{let t=document.querySelector('#toast');t.textContent='Управление окном доступно в приложении';t.style.display='block';setTimeout(()=>t.style.display='none',1800)});const orb=new window.NoxOrb(document.querySelector('#orb'),{variant:'nox',state:'idle',animated:true,scale:.86});new ResizeObserver(()=>orb.resize()).observe(document.querySelector('.sphere'));